 "templates/product.json": "{\n  \"sections\": {\n    \"main\": {\n      \"type\": \"main-product\",\n      \"settings\": {\n        \"sticky_bar\": true\n      },\n      \"blocks\": {\n        \"rating\": {\n          \"type\": \"rating\",\n          \"settings\": {}\n        },\n        \"title\": {\n          \"type\": \"title\",\n          \"settings\": {}\n        },\n        \"subtitle\": {\n          \"type\": \"subtitle\",\n          \"settings\": {}\n        },\n        \"price\": {\n          \"type\": \"price\",\n          \"settings\": {}\n        },\n        \"benefits\": {\n          \"type\": \"benefits\",\n          \"settings\": {}\n        },\n        \"urgency\": {\n          \"type\": \"urgency\",\n          \"settings\": {\n            \"stock_below\": 10,\n            \"show_in_stock\": true\n          }\n        },\n        \"variant_picker\": {\n          \"type\": \"variant_picker\",\n          \"settings\": {\n            \"style\": \"buttons\"\n          }\n        },\n        \"buy_buttons\": {\n          \"type\": \"buy_buttons\",\n          \"settings\": {\n            \"show_quantity\": true,\n            \"show_dynamic_checkout\": true\n          }\n        },\n        \"guarantee\": {\n          \"type\": \"guarantee\",\n          \"settings\": {}\n        },\n        \"trust_icons\": {\n          \"type\": \"trust_icons\",\n          \"settings\": {}\n        },\n        \"payment_icons\": {\n          \"type\": \"payment_icons\",\n          \"settings\": {}\n        },\n        \"delivery\": {\n          \"type\": \"delivery\",\n          \"settings\": {}\n        },\n        \"description\": {\n          \"type\": \"description\",\n          \"settings\": {\n            \"collapsible\": true,\n            \"open\": false\n          }\n        }\n      },\n      \"block_order\": [\n        \"rating\",\n        \"title\",\n        \"subtitle\",\n        \"price\",\n        \"benefits\",\n        \"urgency\",\n        \"variant_picker\",\n        \"buy_buttons\",\n        \"guarantee\",\n        \"trust_icons\",\n        \"payment_icons\",\n        \"delivery\",\n        \"description\"\n      ]\n    },\n    \"testimonials\": {\n      \"type\": \"testimonials\",\n      \"settings\": {\n        \"show_summary\": true,\n        \"layout\": \"slider\",\n        \"scheme\": \"surface\",\n        \"heading\": \"\"\n      }\n    },\n    \"reviews\": {\n      \"type\": \"reviews\",\n      \"settings\": {\n        \"scheme\": \"base\"\n      }\n    },\n    \"faq\": {\n      \"type\": \"faq\",\n      \"settings\": {\n        \"product_questions\": true,\n        \"scheme\": \"surface\",\n        \"heading\": \"\"\n      }\n    }\n  },\n  \"order\": [\n    \"main\",\n    \"testimonials\",\n    \"reviews\",\n    \"faq\"\n  ]\n}\n",
